Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "config": {
    "background": "transparent",
    "view": {
      "stroke": null
    },
    "font": "Segoe UI",
    "axis": {
      "labelColor": "#9AA6B0",
      "labelFont": "Segoe UI",
      "labelFontSize": 10,
      "titleColor": "#9AA6B0",
      "titleFont": "Segoe UI",
      "titleFontWeight": "normal",
      "titleFontSize": 10,
      "domain": false,
      "ticks": false,
      "gridColor": "#2C363E"
    },
    "legend": {
      "labelColor": "#9AA6B0",
      "titleColor": "#9AA6B0",
      "labelFont": "Segoe UI"
    },
    "title": {
      "color": "#C9D3DB",
      "font": "Segoe UI Semibold",
      "fontSize": 12,
      "fontWeight": "normal",
      "anchor": "start",
      "offset": 12
    },
    "locale": {
      "number": {
        "decimal": ",",
        "thousands": ".",
        "grouping": [
          3
        ],
        "currency": [
          "R$ ",
          ""
        ]
      },
      "time": {
        "dateTime": "%A, %e de %B de %Y. %X",
        "date": "%d/%m/%Y",
        "time": "%H:%M:%S",
        "periods": [
          "AM",
          "PM"
        ],
        "days": [
          "Domingo",
          "Segunda",
          "Terça",
          "Quarta",
          "Quinta",
          "Sexta",
          "Sábado"
        ],
        "shortDays": [
          "Dom",
          "Seg",
          "Ter",
          "Qua",
          "Qui",
          "Sex",
          "Sáb"
        ],
        "months": [
          "Janeiro",
          "Fevereiro",
          "Março",
          "Abril",
          "Maio",
          "Junho",
          "Julho",
          "Agosto",
          "Setembro",
          "Outubro",
          "Novembro",
          "Dezembro"
        ],
        "shortMonths": [
          "Jan",
          "Fev",
          "Mar",
          "Abr",
          "Mai",
          "Jun",
          "Jul",
          "Ago",
          "Set",
          "Out",
          "Nov",
          "Dez"
        ]
      }
    }
  },
  "title": {
    "text": "Atingimento da meta da Linha Leve por vendedor · ◆ = tendência com o mês corrente projetado"
  },
  "width": "container",
  "height": "container",
  "transform": [
    {
      "calculate": "datum[''Ating'']",
      "as": "ating"
    },
    {
      "calculate": "min(datum.ating, 1.5)",
      "as": "plot"
    },
    {
      "calculate": "min(datum[''Tend''], 1.5)",
      "as": "tend"
    },
    {
      "calculate": "datum[''Gap''] > 0 ? ''faltam '' + format(datum[''Gap''], '',.0f'') + '' un'' : ''meta batida''",
      "as": "gaptxt"
    }
  ],
  "encoding": {
    "y": {
      "field": "Vendedor",
      "type": "nominal",
      "sort": {
        "field": "ating",
        "op": "min",
        "order": "ascending"
      },
      "axis": {
        "title": null,
        "labelColor": "#F2F4F5",
        "labelFontSize": 12,
        "labelPadding": 12
      }
    }
  },
  "layer": [
    {
      "mark": {
        "type": "bar",
        "color": "#252E36",
        "height": {
          "band": 0.62
        }
      },
      "encoding": {
        "x": {
          "datum": 0
        },
        "x2": {
          "datum": 1.5
        }
      }
    },
    {
      "mark": {
        "type": "bar",
        "color": "#2F3A44",
        "height": {
          "band": 0.62
        }
      },
      "encoding": {
        "x": {
          "datum": 0
        },
        "x2": {
          "datum": 1.0
        }
      }
    },
    {
      "mark": {
        "type": "bar",
        "color": "#38454F",
        "height": {
          "band": 0.62
        }
      },
      "encoding": {
        "x": {
          "datum": 0
        },
        "x2": {
          "datum": 0.8
        }
      }
    },
    {
      "mark": {
        "type": "bar",
        "height": {
          "band": 0.22
        },
        "cornerRadiusEnd": 2
      },
      "encoding": {
        "x": {
          "field": "plot",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1.5
            ],
            "clamp": true
          },
          "axis": {
            "format": ".0%",
            "title": null,
            "values": [
              0,
              0.5,
              0.8,
              1,
              1.25,
              1.5
            ],
            "grid": true,
            "gridDash": [
              2,
              3
            ]
          }
        },
        "color": {
          "condition": {
            "test": "datum.ating < 0.8",
            "value": "#E5484D"
          },
          "value": "#FF8C00"
        },
        "tooltip": [
          {
            "field": "Vendedor"
          },
          {
            "field": "Realizado",
            "format": ",.0f",
            "title": "Vendas Linha Leve (un)"
          },
          {
            "field": "Meta",
            "format": ",.0f",
            "title": "Meta (un)"
          },
          {
            "field": "ating",
            "format": ".1%",
            "title": "Atingimento"
          },
          {
            "field": "Tend",
            "format": ".1%",
            "title": "Tendência"
          },
          {
            "field": "Cob",
            "format": ".1%",
            "title": "Cobertura da carteira"
          }
        ]
      }
    },
    {
      "mark": {
        "type": "tick",
        "color": "#F2F4F5",
        "thickness": 2,
        "size": 30
      },
      "encoding": {
        "x": {
          "datum": 1
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum.tend) && abs(datum.tend - datum.plot) > 0.005"
        }
      ],
      "mark": {
        "type": "point",
        "shape": "diamond",
        "size": 70,
        "filled": true,
        "color": "#F2F4F5",
        "stroke": "#1A2026"
      },
      "encoding": {
        "x": {
          "field": "tend",
          "type": "quantitative"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 10,
        "fontSize": 11,
        "color": "#F2F4F5"
      },
      "encoding": {
        "x": {
          "field": "plot",
          "type": "quantitative"
        },
        "text": {
          "field": "ating",
          "format": ".0%"
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "bottom",
        "dy": -9,
        "fontSize": 9,
        "color": "#7D8A95"
      },
      "encoding": {
        "x": {
          "datum": 1.5
        },
        "text": {
          "field": "gaptxt"
        }
      }
    }
  ]
}'
